MB=TransferLearning.MOpBaseline;
%%
GroupNtats=UniExp.NtatsCellStrip(MB.QueryNTATS(UniExp.ReadQueryTable(TransferLearning.ProjectPath('尝试查询表.xlsx'),"MOpLT"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:459bf902]
%%
%[text] 三个功能组件：
%[text] 1. 刺激响应子，1s前起步，区分声光，不分命中错失
%[text] 2. 命中错失子，1s前起步，区分命中错失
%[text] 3. 强化学习子，1s后达峰，不分命中错失，不分声光 \
%%
Baseline=std(GroupNtats.NTATS(:,1:24,:),[],2).*3;
GroupNtats.RiseBefore1=max(GroupNtats.NTATS(:,25:32,:),[],2)>Baseline;
[PeakValue,PeakTime]=max(GroupNtats.NTATS,[],2);
GroupNtats.PeakAfter1=PeakTime>32&PeakValue>Baseline;
[~,Index]=ismember(GroupNtats.CellUID,MB.Cells.CellUID);
GroupNtats.ZLayer=MB.Cells.ZLayer(Index);
%%
Xs=seconds(linspace(-3,3,width(GroupNtats.NTATS))).';
%%
InheritedMentors=groupsummary(GroupNtats(GroupNtats.RiseBefore1.Learned&GroupNtats.RiseBefore1.TransferHit&~GroupNtats.RiseBefore1.TransferMiss,:),"ZLayer",@(D)TransferLearning.MeanSem(D,1,4),"NTATS");
%%
NewLearners=groupsummary(GroupNtats(~GroupNtats.RiseBefore1.Learned&GroupNtats.RiseBefore1.TransferHit&~GroupNtats.RiseBefore1.TransferMiss,:),"ZLayer",@(D)TransferLearning.MeanSem(D,1,4),"NTATS");
%%
Reinforcors=groupsummary(GroupNtats(~any(GroupNtats.RiseBefore1.Data,3)&all(GroupNtats.PeakAfter1.Data,3),:),"ZLayer",@(D)TransferLearning.MeanSem(D,1,4),"NTATS");
%%
Lines=plot(Xs,permute(NewLearners.fun1_NTATS{1,:,:,1},[2,3,1])); %[output:51e7dab2]
legend(Lines,NewLearners.fun1_NTATS.Dimensions.IndexNames{3},Location=MATLAB.Graphics.OptimizedLegendLocation(Lines)); %[output:51e7dab2]

